"""generated: generated files are detected by header; plan check warns on them; the scope guard allows them next to a changed source."""

import json
import os
import subprocess
import sys
import unittest

TOOLS = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, TOOLS)
from pipeline import generated, plan_check, plan_rules, scopeguard  # noqa: E402
from pipeline.configuration import GENERATED_MARKER_RE  # noqa: E402
from tests.support.tmpdirs import tracked_mkdtemp  # noqa: E402

HEADER = "# Index\n\nGenerated by `docs_index.py` - do not edit by hand\n"


class DetectTest(unittest.TestCase):
    def setUp(self):
        self.t = tracked_mkdtemp()

    def write(self, name, text):
        with open(f"{self.t}/{name}", "w") as f:
            f.write(text)

    def test_marker_in_head_is_found_case_insensitive(self):
        self.write("a.md", HEADER)
        self.write("b.md", "x\nDO NOT EDIT\n")
        self.write("c.md", "plain\n")
        self.assertEqual(generated.generated_among(self.t, ["a.md", "b.md", "c.md", "none.md"], GENERATED_MARKER_RE), ["a.md", "b.md"])

    def test_marker_below_the_head_is_ignored(self):
        self.write("a.md", "1\n2\n3\n4\n5\ngenerated by x\n")
        self.assertEqual(generated.generated_among(self.t, ["a.md"], GENERATED_MARKER_RE), [])

    def test_setting_overrides_the_default_marker(self):
        self.write("pipeline.json", json.dumps({"generated_marker": "AUTOGEN"}))
        self.assertEqual(generated.marker(self.t), "AUTOGEN")
        os.remove(f"{self.t}/pipeline.json")
        self.assertEqual(generated.marker(self.t), GENERATED_MARKER_RE)


class PlanWarnTest(unittest.TestCase):
    def setUp(self):
        self.t = tracked_mkdtemp()
        self.repo = f"{self.t}/repo"
        self.d = f"{self.t}/.work/s"
        os.makedirs(f"{self.repo}/docs")
        os.makedirs(self.d)
        with open(f"{self.repo}/docs/INDEX.md", "w") as f:
            f.write(HEADER)
        with open(f"{self.repo}/docs/guide.md", "w") as f:
            f.write("guide\n")
        for cmd in (["init", "-q"], ["add", "-A"], ["-c", "user.name=t", "-c", "user.email=t@t", "commit", "-qm", "i"]):
            subprocess.run(["git", "-C", self.repo, *cmd], check=True, capture_output=True)

    def task(self, paths):
        with open(f"{self.d}/task-1.md", "w") as f:
            f.write(f"Predicted paths: {paths}\nGoal: x\n")

    def test_generated_predicted_path_warns(self):
        self.task("docs/INDEX.md, docs/guide.md")
        got = plan_rules.check_generated_paths(self.d, "task-1", self.repo)
        self.assertEqual(len(got), 1)
        self.assertTrue(got[0].startswith("generated:"))
        self.assertIn("docs/INDEX.md", got[0])
        self.assertNotIn("guide.md", got[0])
        self.assertEqual(plan_check.errors_of(got), [])

    def test_no_warning_for_hand_written_or_untracked_files(self):
        self.task("docs/guide.md, docs/new.md")
        self.assertEqual(plan_rules.check_generated_paths(self.d, "task-1", self.repo), [])


class ScopeTest(unittest.TestCase):
    def test_generated_file_is_allowed_when_a_predicted_source_changed(self):
        got = scopeguard.unplanned(["src/widget.py", "docs/INDEX.md"], ["src/widget.py"], "Goal", (), "d", generated=["docs/INDEX.md"])
        self.assertEqual(got, [])

    def test_generated_file_alone_is_still_a_finding(self):
        got = scopeguard.unplanned(["docs/INDEX.md"], ["src/widget.py"], "Goal", (), "d", generated=["docs/INDEX.md"])
        self.assertEqual(got, ["docs/INDEX.md"])

    def test_other_outside_files_still_count(self):
        got = scopeguard.unplanned(["src/widget.py", "docs/INDEX.md", "core/a.py"], ["src/widget.py"], "Goal", (), "d", generated=["docs/INDEX.md"])
        self.assertEqual(got, ["core/a.py"])


if __name__ == "__main__":
    unittest.main()
